drop policy if exists incorporaciones_storage_update on storage.objects;create policy incorporaciones_storage_update on storage.objects for update to authenticated using(bucket_id='incorporaciones'and exists(select 1 from public.incorporaciones e where e.id::text=(storage.foldername(name))[1]and public.incorporacion_can_access(e)))with check(bucket_id='incorporaciones');
revoke all on function public.incorporacion_can_assign(uuid,text),public.incorporacion_set_estado(uuid,public.incorporacion_estado,text),public.incorporacion_rechazar_contrato_firmado(uuid,text)from public,anon;grant execute on function public.incorporacion_can_assign(uuid,text),public.incorporacion_set_estado(uuid,public.incorporacion_estado,text),public.incorporacion_rechazar_contrato_firmado(uuid,text)to authenticated;grant select,insert,update on public.incorporaciones,public.incorporacion_documentos to authenticated;grant select on public.incorporacion_historial to authenticated;
